import sys

def construct_magic_grid(n):
    grid = [[0] * n for _ in range(n)]
    value = 0
    for i in range(n // 4):
        for j in range(n // 4):
            base = 16 * (i * (n // 4) + j)
            for x in range(4):
                for y in range(4):
                    if (x + y) % 2 == 0:
                        grid[4 * i + x][4 * j + y] = base + value
                    else:
                        grid[4 * i + x][4 * j + y + 2] = base + value
                    value += 1
    return grid

def main():
    import sys
    n = int(sys.stdin.read().strip())
    grid = construct_magic_grid(n)
    for row in grid:
        print(" ".join(map(str, row)))

if __name__ == "__main__":
    main()
